package com.jnapanam.sportszone.payment.controller;import com.jnapanam.sportszone.payment.dto.*;import com.jnapanam.sportszone.payment.service.PaymentService;import jakarta.validation.Valid;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin/payments")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN')")public class AdminPaymentController{private final PaymentService service;public AdminPaymentController(PaymentService s){service=s;}@GetMapping public List<PaymentResponse>all(){return service.all();}@PostMapping("/{id}/refunds")public RefundResponse refund(@PathVariable UUID id,@Valid@RequestBody RefundRequest r){return service.refund(id,r);}}
